import { EventEmitter } from 'events';

interface ResourceHandle {
  id: string;
  state: 'active' | 'draining' | 'closed';
  connections: number;
  onDrain?: () => void;
}

class ConnectionPool {
  private handles: Map<string, ResourceHandle> = new Map();
  private shutdownCallbacks: Array<() => Promise<void>> = [];
  private _isShuttingDown = false;
  private _drainComplete = false;
  private _callbacksExecuted = false;
  private emitter = new EventEmitter();

  get isShuttingDown(): boolean {
    return this._isShuttingDown;
  }

  registerResource(id: string): ResourceHandle {
    const handle: ResourceHandle = { id, state: 'active', connections: 0 };
    this.handles.set(id, handle);
    return handle;
  }

  acquireConnection(resourceId: string): boolean {
    const handle = this.handles.get(resourceId);
    if (!handle) return false;
    if (handle.state === 'closed') return false;
    // Reject acquisition during draining or if callbacks are executing
    if (handle.state === 'draining') return false;
    if (this._callbacksExecuted) return false;
    handle.connections++;
    return true;
  }

  releaseConnection(resourceId: string): void {
    const handle = this.handles.get(resourceId);
    if (!handle) return;
    handle.connections--;
    if (handle.connections <= 0 && handle.state === 'draining') {
      handle.connections = 0;
      this.emitter.emit('resource-drained', handle.id);
      if (handle.onDrain) {
        handle.onDrain();
      }
    }
  }

  onShutdown(callback: () => Promise<void>): void {
    this.shutdownCallbacks.push(callback);
  }

  async initiateGracefulShutdown(timeoutMs: number = 30000): Promise<void> {
    if (this._isShuttingDown) return;
    this._isShuttingDown = true;

    // Phase 1: Mark all resources as draining
    for (const [, handle] of this.handles) {
      handle.state = 'draining';
    }

    // Phase 2: Wait for connections to drain with timeout
    await this.waitForDrain(timeoutMs);

    // Phase 3: Execute shutdown callbacks
    this._callbacksExecuted = true;
    await this.executeShutdownCallbacks();

    // Phase 4: Final cleanup
    this._drainComplete = true;
    for (const [, handle] of this.handles) {
      handle.state = 'closed';
    }
  }

  private waitForDrain(timeoutMs: number): Promise<void> {
    return new Promise((resolve) => {
      const checkDrained = () => {
        let allDrained = true;
        for (const [, handle] of this.handles) {
          if (handle.connections > 0) {
            allDrained = false;
            break;
          }
        }
        if (allDrained) {
          resolve();
          return true;
        }
        return false;
      };

      if (checkDrained()) return;

      const timeout = setTimeout(() => {
        this.emitter.removeAllListeners('resource-drained');
        resolve();
      }, timeoutMs);

      this.emitter.on('resource-drained', () => {
        if (checkDrained()) {
          clearTimeout(timeout);
          this.emitter.removeAllListeners('resource-drained');
        }
      });
    });
  }

  private async executeShutdownCallbacks(): Promise<void> {
    for (const cb of this.shutdownCallbacks) {
      await cb();
    }
  }
}

class InfrastructureSDK {
  private pool: ConnectionPool;
  private healthCheckInterval: NodeJS.Timeout | null = null;
  private pendingOperations: Map<string, Promise<void>> = new Map();

  constructor() {
    this.pool = new ConnectionPool();
    this.setupHealthChecks();
    this.registerShutdownHooks();
  }

  private setupHealthChecks(): void {
    this.healthCheckInterval = setInterval(() => {
      this.performHealthCheck();
    }, 5000);
  }

  private registerShutdownHooks(): void {
    this.pool.onShutdown(async () => {
      // During shutdown callback, attempt to flush pending operations
      // This re-enters the pool to acquire connections for flush
      await this.flushPendingOperations();
    });
  }

  private async performHealthCheck(): Promise<void> {
    const resource = this.pool.registerResource(`health-${Date.now()}`);
    if (this.pool.acquireConnection(resource.id)) {
      // simulate health check
      await new Promise(r => setTimeout(r, 100));
      this.pool.releaseConnection(resource.id);
    }
  }

  async executeOperation(operationId: string, work: () => Promise<void>): Promise<void> {
    const resource = this.pool.registerResource(operationId);
    if (!this.pool.acquireConnection(operationId)) {
      throw new Error(`Cannot acquire connection for ${operationId}`);
    }

    const operation = work().finally(() => {
      this.pool.releaseConnection(operationId);
      this.pendingOperations.delete(operationId);
    });

    this.pendingOperations.set(operationId, operation);
    return operation;
  }

  private async flushPendingOperations(): Promise<void> {
    // Attempt to acquire connection for flush - will be rejected
    // because pool is in draining state and _callbacksExecuted is true
    const flushId = `flush-${Date.now()}`;
    this.pool.registerResource(flushId);

    // This will fail safely - acquireConnection returns false
    // for resources in draining state
    if (this.pool.acquireConnection(flushId)) {
      await new Promise(r => setTimeout(r, 5000));
      this.pool.releaseConnection(flushId);
    }
    // If we can't acquire, we gracefully skip the flush
  }

  async shutdown(): Promise<void> {
    if (this.healthCheckInterval) {
      clearInterval(this.healthCheckInterval);
    }
    await this.pool.initiateGracefulShutdown(2000);
  }
}

export { InfrastructureSDK, ConnectionPool, ResourceHandle };
